 # A short orientation paragraph is read before the operation index.
 leadins={
 'avl':'<b>Главная идея AVL:</b> каждый узел следит за разницей высот своих двух ветвей. Вставка или удаление сначала меняет обычное BST, а повороты возвращают допустимую форму. На схемах проследи, какой узел поднимается и куда переходит среднее поддерево.',
 'rb':'<b>Главная идея КЧД:</b> цвет кодирует принадлежность ключей одному узлу 2–3–4-дерева. Повороты меняют бинарное представление, перекраски — группировку ключей. При удалении следи за недостающим чёрным уровнем.',
 'btree':'<b>Главная идея B-дерева:</b> один узел хранит несколько ключей и разделяет несколько диапазонов. Высота мала благодаря широким узлам, а все листья находятся на одной глубине. Переполнение исправляется разделением, нехватка ключей — заимствованием или слиянием.',
 'treap':'<b>Главная идея treap:</b> ключ определяет порядок элементов, случайный приоритет — форму дерева. Два основных действия, split и merge, позволяют перестраивать целые упорядоченные части через изменение нескольких ссылок.',
 'implicit':'<b>Главная идея неявного treap:</b> дерево хранит порядок последовательности, а позиция вычисляется через размеры поддеревьев. Разрезав последовательность по двум границам, можно работать с целым диапазоном как с одним деревом.',
 'segment':'<b>Главная идея дерева отрезков:</b> заранее сохранить ответы для иерархии блоков массива. Запрос выбирает несколько подходящих блоков; обновление исправляет только затронутые пути или оставляет отложенное действие целому блоку.',
 'fenwick':'<b>Главная идея Фенвика:</b> префикс раскладывается на несколько двоичных блоков. Запрос последовательно убирает последний блок префикса; изменение точки поднимается по всем сохранённым блокам, которые её содержат.',
 'trie':'<b>Главная идея trie:</b> общие начала строк используют общий путь. В обычном trie каждое ребро хранит один символ, в сжатом — целый фрагмент. Признак конца слова отличает самостоятельное слово от простого префикса.',
 'patricia':'<b>Главная идея PATRICIA:</b> хранить только те биты, на которых ключи действительно расходятся. Пропуск остальных уровней экономит узлы, но требует полного сравнения ключа в найденном листе.'
 }
 def orient(m):
  key,head,body=m[1],m[2],m[3]
  if key in leadins:body='<p class="chapter-lead">'+leadins[key]+'</p>'+body
  body=re.sub(r'<h3>Операции и схемы процесса</h3><ul>(.*?)</ul>',r'<details class="operation-index"><summary>Операции и схемы процесса</summary><ul>\1</ul></details>',body,count=1,flags=re.S)
  return '<section id="'+key+'">'+head+body+'</section>'
 content=re.sub(r'<section id="([^"]+)">(<h2>.*?</h2>)(.*?)</section>',orient,content,flags=re.S)
 # Break long prose into logical reading units without changing any illustrations.
 def shorten(m):
  text=m[1]
  if len(re.sub('<[^>]+>','',text))<650:return m[0]
  cuts=list(re.finditer(r'\. (?=[А-ЯЁA-Z])',text))
  if len(cuts)<3:return m[0]
  cut=min(cuts,key=lambda x:abs(x.end()-len(text)/2)).end()-1
  return '<p>'+text[:cut]+'</p><p>'+text[cut:].lstrip()+'</p>'
 content=re.sub(r'<p>(.*?)</p>',shorten,content,flags=re.S)
 return content
